// `crypto.randomUUID()` est indisponible : le bac a sable interdit require().
// `$execution.id` est unique par execution (n8n-workflows#476).
const nouvelId = () => 'job_' + $execution.id + '_' + Date.now().toString(36);
const webhookData = $('Webhook').first().json;

// Generate or use provided job_id
const job_id = webhookData.body.job_id || nouvelId();
const callback_url = webhookData.body.callback_url;

return [{
  json: {
    ...webhookData,
    _async: {
      job_id,
      callback_url,
      started_at: new Date().toISOString()
    }
  }
}];

