const items = $input.all();
const jobContext = $('Store Job Context').first().json;
const startTime = Date.now();

const results = items.map(item => {
  // Check for API errors
  if (item.json.error) {
    return {
      json: {
        success: false,
        job_id: jobContext._async.job_id,
        error: {
          code: item.json.error.code || 500,
          message: item.json.error.message || 'Mistral API error',
          status: 'API_ERROR'
        },
        meta: {
          provider: 'mistral-ocr',
          execution_mode: jobContext.body.execution_mode || 'online'
        },
        _async: jobContext._async
      }
    };
  }

  try {
    const content = item.json.choices?.[0]?.message?.content || '{}';
    // Try to extract JSON from the response
    let parsed;
    const jsonMatch = content.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      parsed = JSON.parse(jsonMatch[0]);
    } else {
      parsed = { tables: [], table_count: 0 };
    }

    // Generate markdown representation
    let rawMarkdown = '';
    if (parsed.tables && parsed.tables.length > 0) {
      parsed.tables.forEach((table, idx) => {
        if (idx > 0) rawMarkdown += '\n\n';
        // Header
        if (table.headers && table.headers.length > 0) {
          rawMarkdown += '| ' + table.headers.join(' | ') + ' |\n';
          rawMarkdown += '|' + table.headers.map(() => '---').join('|') + '|\n';
        }
        // Rows
        if (table.rows) {
          table.rows.forEach(row => {
            rawMarkdown += '| ' + row.join(' | ') + ' |\n';
          });
        }
      });
    }

    return {
      json: {
        success: true,
        _trace: {
          service_response: item.json,
          model: 'pixtral-12b-2409',
          tokens: { input: null, output: null },
          latency_ms: Date.now() - startTime
        },
        job_id: jobContext._async.job_id,
        data: {
          tables: parsed.tables || [],
          raw_markdown: rawMarkdown || null,
          table_count: parsed.table_count || parsed.tables?.length || 0
        },
        meta: {
          provider: 'mistral-ocr',
          model: 'pixtral-12b-2409',
          execution_mode: jobContext.body.execution_mode || 'online',
          timings: {
            ocr_ms: Date.now() - startTime,
            parse_ms: 10
          }
        },
        _async: jobContext._async
      }
    };
  } catch (e) {
    return {
      json: {
        success: false,
        job_id: jobContext._async.job_id,
        error: {
          code: 500,
          message: 'Failed to parse OCR response: ' + e.message,
          status: 'PARSE_ERROR'
        },
        meta: {
          provider: 'mistral-ocr',
          execution_mode: jobContext.body.execution_mode || 'online'
        },
        _async: jobContext._async
      }
    };
  }
});

return results;

// Signature deleguee au noeud Crypto natif qui suit : le bac a sable n8n
// interdit require('crypto'). Cf. n8n-workflows#476.
const item = $input.first();
const asyncContext = item.json._async;

// Prepare callback body (without _async internal data)
const callbackBody = { ...item.json };
delete callbackBody._async;

// Generate HMAC signature
const corps_json = JSON.stringify(callbackBody);

return [{
  json: {
    callback_url: asyncContext.callback_url,
    callback_body: callbackBody,
    corps_json: corps_json,
    rappel_signable: !!$env.N8N_WEBHOOK_SECRET
  }
}];

